// pages/Auth/Login.jsx

import React, { useState, useContext } from 'react';
import { useNavigate, Link } from 'react-router-dom';
import { AuthContext } from '../../context/AuthContext';

function Login() {
  const navigate = useNavigate();
  const { login } = useContext(AuthContext);
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [showPassword, setShowPassword] = useState(false);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(null);

  const handleSubmit = async (e) => {
    e.preventDefault();
    setError(null);
    if (!email || !password) return setError('이메일과 비밀번호를 입력하세요.');
    try {
      setLoading(true);
      await login({ email, password });
      navigate('/');
    } catch (err) {
      setError(err.response?.data?.message || err.message || '로그인 실패');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div style={{ maxWidth: 420, margin: '40px auto', padding: 20 }}>
      <div className="card">
        <h2 style={{ marginBottom: 8 }}>로그인</h2>
        <p style={{ color: '#666', marginTop: 0 }}>계정으로 서비스를 이용하세요.</p>

        <form onSubmit={handleSubmit}>
          <label style={{ display: 'block', marginTop: 12 }}>
            <div style={{ fontSize: 13, color: '#333' }}>이메일</div>
            <input className="fade-in" type="email" value={email} onChange={(e) => setEmail(e.target.value)} style={{ width: '100%', padding: 10, marginTop: 6, borderRadius: 6, border: '1px solid #ddd' }} />
          </label>

          <label style={{ display: 'block', marginTop: 12, position: 'relative' }}>
            <div style={{ fontSize: 13, color: '#333' }}>비밀번호</div>
            <input className="fade-in" type={showPassword ? 'text' : 'password'} value={password} onChange={(e) => setPassword(e.target.value)} style={{ width: '100%', padding: 10, marginTop: 6, borderRadius: 6, border: '1px solid #ddd' }} />
            <button type="button" onClick={() => setShowPassword(!showPassword)} style={{ position: 'absolute', right: 12, top: 36, border: 'none', background: 'transparent', cursor: 'pointer' }} aria-label="toggle-password">
              {showPassword ? '숨기기' : '보기'}
            </button>
          </label>

          <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginTop: 12 }}>
            <label style={{ fontSize: 13, color: '#666' }}><input type="checkbox" style={{ marginRight: 8 }} /> 로그인 유지</label>
            <Link to="/register" style={{ fontSize: 13 }}>회원가입</Link>
          </div>

          {error && <div style={{ marginTop: 12, color: 'crimson' }}>{error}</div>}

          <button className="btn btn-primary" type="submit" disabled={loading} style={{ marginTop: 16, width: '100%' }}>
            {loading ? '로그인 중...' : '로그인'}
          </button>
        </form>
      </div>
    </div>
  );
}

export default Login;
